fn main() {
    println!("cargo:rerun-if-changed=capabilities");

    // Listing the commands opts out of Tauri's default allow-all for app commands.
    // Each name gets `allow-<slug>` and `deny-<slug>` permissions. Only the main
    // window capability grants the allows. Do not grant the deny permissions:
    // Tauri 2.11 applies a command deny to every window.
    //
    // The default permissions glob would also read `permissions/autogenerated`
    // and define each permission twice. This pattern matches no extra files.
    let manifest = tauri_build::AppManifest::new()
        .commands(&[
            "node_status",
            "fund_state",
            "fund_start",
            "funding_address",
            "payments_balance",
            "identity_restore",
            "pairing_status",
            "pairing_retry",
            "node_overview",
            "live_link",
            "peers_list",
            "rooms_list",
            "room_members",
            "messages_list",
            "room_thread",
            "price_quote",
            "first_contact_quote",
            "introduction_mine",
            "introduction_read",
            "introduction_open",
            "front_door_mine",
            "front_door_read",
            "front_door_open",
            "front_door_publish",
            "front_door_hash_bytes",
            "sponsor_status",
            "sponsor_offer",
            "sponsor_candidate",
            "sponsor_owner_approval",
            "sponsor_reconcile",
            "sponsor_cancel",
            "sponsor_request",
            "sponsor_request_status",
            "first_contact_request",
            "first_contact_status",
            "first_contact_cancel",
            "payments_overview",
            "energy_read",
            "membrane_read",
            "spend_status",
            "spend_request",
            "spend_lock",
            "spend_reconcile",
            "budget_status",
            "budget_approve",
            "budget_set",
            "budget_pause",
            "budget_resume",
            "message_send",
            "message_retry",
            "spend_dismiss_undelivered",
            "room_quote",
            "invoice_create",
            "invoice_amount",
            "payment_pay",
            "payment_keysend",
            "invite_create",
            "invite_redeem",
            "file_price",
            "file_send",
            "voice_note_fetch",
            "file_fetch",
            "file_save",
            "call_quote",
            "call_signal",
            "ai_read",
            "ai_providers",
            "ai_disclose",
            "ai_send",
            "ai_cancel",
            "ai_local_status",
            "ai_local_select",
            "ai_local_clear",
        ])
        .permissions_path_pattern("./permissions/manual/**/*");

    let mut attributes = tauri_build::Attributes::new().app_manifest(manifest);
    // Release bundles keep the main capability only. The assistant window is not
    // created in release, and a window with no capability has no grants. Debug
    // and test builds still compile capabilities/assistant.json so the ACL test
    // can resolve that label.
    if std::env::var("PROFILE").as_deref() == Ok("release") {
        attributes = attributes.capabilities_path_pattern("./capabilities/default.json");
    }

    if let Err(error) = tauri_build::try_build(attributes) {
        panic!("failed to run tauri-build: {error}");
    }
}
